<!--vbase-->
<template>
  <MessageBanner
    v-if="isReadOnly || (error && !isDocumentPermissionError)"
    :message="error_message"
    :messageCategoryClass="bannerBg"
  />
  <SubHeader
    name="tasks"
    :label="$t('tasks')"
    :show_expiry_alert="true"
    :onSearch="false"
  />

  <div v-if="!doc_fetch_error || isDocumentPermissionError" class="row q-pl-md">
    <div
      :class="!expert_mode ? 'full-width' : 'right_section'"
      id="right_section"
    >
      <q-splitter
        v-model="splitterModel"
        class="full-width height-100vh-95px"
      >
        <template v-slot:before>
          <template v-if="task">
            <EmailTask v-if="task.type === 'email'" />
            <Task v-else />
          </template>
        </template>
        <template v-slot:separator> </template>

        <template v-slot:after>
          <div
            v-if="isDocumentPermissionError"
            class="column items-center justify-center full-height document-permission-notice"
            data-test="task-document-permission-notice"
          >
            <q-icon name="lock_outline" size="48px" color="grey-6" />
            <span class="q-mt-md document-permission-notice__text">
              {{ $t('doc_permission_error') }}
            </span>
          </div>
          <ImageComponent
            v-else-if="showDocumentPane"
            :renderOpenWindoIcon="true"
            :docName="record.filename"
            :docImages="record.images"
          >
          </ImageComponent>
        </template>
      </q-splitter>
    </div>
    <!-- right section -->
  </div>
  <div class="row bg-grey-2 q-pl-md q-pr-md q-pb-md" v-else>
    <ErrorDocumentView />
  </div>

  <Loader />

  <q-footer class="validation-status-bar back-white">
    <q-toolbar class="row justify-start">
      <span
        class="footer-filename text-primary cursor-pointer"
        @click="openDocument()"
        >{{ record.filename }}</span
      >
      <q-separator vertical class="q-mx-md" />
      <span class="col-3 footer-status-message">{{
        currentDisplayedMessage
      }}</span>
    </q-toolbar>
  </q-footer>
</template>

<script lang="ts">

import { storeToRefs } from 'pinia';
import Task from './Detail/Task.vue';
import { objLen } from 'src/utils/general';
import { defineComponent, ref } from 'vue';
import helperUtil from 'src/utils/helperUtil';
import EmailTask from './Detail/EmailTask.vue';
import Loader from 'src/components/Loader.vue';
import documentUtil from 'src/utils/documentUtil';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import helper from 'src/pages/FieldValidation/helper';
import { useImageAuth } from 'src/composables/useImageAuth';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import MessageBanner from 'src/components/MessageBanner.vue';
import { notify } from 'src/components/notifications/notify';
import ImageComponent from 'src/components/ImageComponent.vue';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import ErrorDocumentView from 'src/pages/Errors/ErrorDocumentView.vue';

import {
  useDocumentStore,
  useTaskStore,
  useDropdownStore,
  useGroupDropdownStore} from 'src/store/main';

export default defineComponent({
  el: '#app',
  mixins: [helperUtil,
    helperMixin,
    documentUtil,
    displayFieldLabel,
    helper,
  ],
  components: {
    Loader,
    ErrorDocumentView,
    ImageComponent,
    Task,
    EmailTask,
    MessageBanner,
    SubHeader,
  },
  watch: {
    processing: function (val) {
      if (val) {
        this.showLoading();
      } else {
        this.hideLoading();
      }
    },
  },
  data() {
    return {
      docId: '',
      emailType: '',
      currentDisplayedMessage: ref(''),
    };
  },

  beforeRouteLeave(to: any, from: any, next: any) {
    // Before leaving this page, lets first reset everything
    this.record = {};
    this.page = 1;
    next();
  },

  mounted: function () {
    this.init();
    window.addEventListener('resize', this.windowResize);
    document.body.addEventListener('click', this.mouseClicked, true);
    document.addEventListener(
      'dispatch_status_bar_message',
      this.dispatchTaskbarMessage,
    );
  },

  unmounted: function () {
    window.removeEventListener('resize', this.windowResize);
    document.removeEventListener(
      'dispatch_status_bar_message',
      this.dispatchTaskbarMessage,
    );
  },

  computed: {
    // A document the user may not view must not swallow the whole screen:
    // the task itself is still theirs to work on, so the task panel stays and
    // only the document half is replaced by a notice. Other document failures
    // (not found, invalid, error status) keep the full-screen error view.
    isDocumentPermissionError(): boolean {
      return this.error === true && this.error_message === 'permission';
    },

    // ImageComponent restores this tab's last cached document when it mounts
    // (setRecordFromCache keys off a per-tab marker, not the requested doc id),
    // so mounting it before this document has loaded paints the previously
    // opened document for a moment.
    showDocumentPane(): boolean {
      return this.doc_loaded === true && !this.isDocumentPermissionError;
    },
  },

  methods: {
    dispatchTaskbarMessage(event: any) {
      if (!event.detail.message) {
        return;
      }
      this.currentDisplayedMessage = event.detail.message;
    },

    async init() {
      try {
        this.data_fetched = false;
        this.showLoading();
        this.resetTaskStore();

        await this.prepareUsersDropdown();
        await this.getGroups();
        const id = this.$route.params.id as string;
        await this.getTask(id, false);

        this.docId = this.task.document_id
          ? this.task.document_id
          : this.task.doc_id;

        if (this.docId) {
          await this.getInvoiceDataByDocId(this.docId);
        }

        this.data_fetched = true;
        if (
          !this.docId ||
          !this.record ||
          Object.keys(this.record).length === 0 ||
          this.record.success === false ||
          this.doc_fetch_error
        ) {
          this.hideLoading();
          return;
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async getInvoiceDataByDocId(docId: string) {
      try {
        this.record = [];
        if (!docId) {
          this.error_message = 'Document not found — it may have been deleted.';
          this.error = true;
          this.doc_fetch_error = true;
          return;
        }
        const response: any = await this.getDocumentById(docId);
        if (response != null && response.success === false) {
          this.error_message = response.message || 'Document not found — it may have been deleted.';
          this.error = true;
          this.currentDisplayedMessage = this.error_message;
        }
      } catch (err) {
        this.error_message = 'Document not found — it may have been deleted.';
        this.error = true;
        this.doc_fetch_error = true;
      }
    },

    hasApiData() {
      return objLen(this.record) !== 0 && !this.doc_fetch_error;
    },

    goToList() {
      this.$router.push('/tasks');
    },

    openDocument() {
      if (
        this.record.hasOwnProperty('has_layout') &&
        String(this.record.has_layout) === 'true'
      ) {
        this.$router.push('/field_validation_v1/' + this.record.doc_id);
        return;
      }
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    doc_store.$reset();
    const {
      record,
      page,
      error,
      bannerBg,
      doc_loaded,
      has_ai_table,
      error_message,
    } = storeToRefs(doc_store);
    const { getDocumentById } = doc_store;

    const { tokenQueryParam, refreshTokenParam } = useImageAuth();
    const task_store = useTaskStore();
    const { task, data_fetched } = storeToRefs(task_store);
    const { getTask, resetTaskStore } = task_store;
    const dropdown_store = useDropdownStore();
    const { prepareUsersDropdown } = dropdown_store;

    const group_dropdown_store = useGroupDropdownStore();
    const { getGroups } = group_dropdown_store;

    return {
      error_message,
      data_fetched,
      getTask,
      getGroups,
      resetTaskStore,
      getDocumentById,
      prepareUsersDropdown,
      task,
      bannerBg,
      has_ai_table,
      doc_loaded,
      record,
      error,
      doc_fetch_error: ref(error),
      page,
      isReadOnly: ref(false),
      imageFieldSplitter: ref(36), // start at 150px
      is_admin: ref(false),
      tokenQueryParam,
      splitterModel: ref(50), // start at 50%
      expert_mode: ref(false),
    };
  },
});
</script>

