<template>
  <q-card flat class="popup-background q-pa-lg">
    <div class="row full-width q-mb-sm">
      <div class="col-9 secondary-c-text text-h6 text-weight-bold">
        {{ $t('task_details') }}
      </div>

      <div
        class="col-3 secondary-c-text text-h6 text-weight-bold q-ml-auto"
        v-if="assign_to_me"
      >
        <f-btn
          :label="$t('assign_to_me')"
          appearance="primary"
          @click="AssignToMe"
          class="float-right"
        />
      </div>
    </div>

    <div class="row q-col-gutter-md q-mb-sm">
      <div class="col-12">
        <q-input
          dense
          outlined
          v-model="task.title"
          label="Name"
          class="custom-input"
        />
      </div>
    </div>

    <div class="row q-col-gutter-md q-mb-sm">
      <div class="col-6">
        <q-select
          dense
          outlined
          v-model="task.priority"
          :options="priorityOptions"
          label="Priority"
          emit-value
          map-options
          class="custom-select"
        />
      </div>
      <div class="col-6">
        <q-select
          dense
          outlined
          v-model="task.status"
          :options="statusOptions"
          label="Status"
          emit-value
          map-options
          class="custom-select"
        />
      </div>
    </div>

    <div class="row q-col-gutter-md q-mb-sm">
      <div class="col-6">
        <q-input
          dense
          outlined
          readonly
          class="back-white"
          v-model="task.deadline"
          :label="$t('deadline')"
        >
          <template v-slot:append>
            <q-icon name="event" class="cursor-pointer" @click.stop>
              <q-tooltip>Select Date-Time</q-tooltip>
              <q-popup-proxy
                cover
                v-model="show_calender"
                transition-show="scale"
                transition-hide="scale"
                ref="qDateProxy"
              >
                <q-date
                  v-model="task.deadline"
                  @update:model-value="
                    (val: any) => {
                      OnDateChange(val);
                    }
                  "
                  minimal
                >
                  <div class="row items-center">
                    <q-icon
                      name="schedule "
                      class="icon-grey q-mr-sm"
                      size="20px"
                    />
                    <q-select
                      dense
                      outlined
                      :options="timeOptions"
                      class="back-white"
                      v-model="task.time"
                      @update:model-value="
                        (val: any) => {
                          OnTimeChange(val);
                        }
                      "
                      :label="$t('set_time')"
                      emit-value
                      map-options
                    />
                  </div>
                  <div class="row items-center justify-end q-gutter-sm">
                    <f-btn
                      :label="$t('close')"
                      appearance="negative-tertiary"
                      v-close-popup
                    />
                    <f-btn label="Ok" appearance="tertiary" v-close-popup />
                  </div>
                </q-date>
              </q-popup-proxy>
            </q-icon>
          </template>
        </q-input>
      </div>
      <div class="col-6">
        <q-select
          clearable
          use-input
          dense
          outlined
          @filter="filterGroupsEvent"
          :options="filteredGroupList"
          :loading="groups_loading"
          hide-dropdown-icon
          emit-value
          map-options
          class="back-white"
          v-model="task.assigned_to_group_id"
          :label="$t('assigned_to_group')"
          v-if="task['assigned_to_group']"
        >
          <template v-slot:selected-item="scope">
            <div class="ellipsis">{{ scope.opt.label }}</div>
          </template>
          <template v-slot:no-option>
            <q-item>
              <q-item-section> No results </q-item-section>
            </q-item>
          </template>
          <template v-slot:append>
            <q-icon
              v-if="
                errors.hasOwnProperty('assigned_to_group_id') &&
                errors['assigned_to_group_id'] != ''
              "
              flat
              dense
              name="error"
              size="24px"
              color="red"
            >
              <q-tooltip class="bg-red line-error-tooltip">
                {{ errors['assigned_to_group_id'] }}
              </q-tooltip>
            </q-icon>
          </template>
        </q-select>
      </div>
    </div>

    <div class="row q-col-gutter-md q-mb-sm">
      <div class="col-6">
        <q-input
          dense
          outlined
          :model-value="task.type === 'email' ? 'E-Mail' : task.type"
          label="Source"
          class="custom-input"
          readonly
        />
      </div>

      <div class="col-6">
        <q-select
          dense
          outlined
          v-model="task.categories"
          :options="categoryOptions"
          label="Category"
          multiple
          emit-value
          map-options
          class="custom-select"
        >
          <template v-slot:selected>
            <q-chip
              v-for="cat in task.categories"
              :key="cat"
              color="grey-3"
              text-color="black"
              class="q-mr-xs q-mb-xs"
            >
              {{ cat }}
            </q-chip>
          </template>
        </q-select>
      </div>
    </div>

    <div class="row q-col-gutter-md q-mb-sm">
      <div class="col-12">
        <q-input
          dense
          outlined
          v-model="task.email_data.sender"
          label="From"
          class="custom-input"
        />
      </div>
    </div>

    <div class="row q-col-gutter-md q-mb-sm">
      <div class="col-12">
        <q-input
          dense
          outlined
          v-model="task.email_data.subject"
          label="Subject"
          class="custom-input"
        />
      </div>
    </div>

    <div class="row q-col-gutter-md q-mb-sm">
      <div class="col-12">
        <q-input
          dense
          outlined
          v-model="task.created_on"
          label="Date"
          class="custom-input"
        />
      </div>
    </div>

    <div class="row q-col-gutter-md q-mb-sm">
      <div class="col-12">
        <div class="q-mb-xs text-caption text-grey-7">
          <q-icon
            name="attach_file"
            style="transform: rotate(220deg); font-size: 16px"
            class="q-mr-sm"
          />
        </div>
        <div>
          <q-chip
            v-for="file in task.attachments"
            :key="file.id"
            icon="attach_file"
            color="grey-3"
            text-color="black"
            class="q-mr-xs q-mb-xs"
          >
            {{ file.name }}
          </q-chip>
        </div>
      </div>
    </div>

    <div class="q-mb-md">
      <q-input
        dense
        outlined
        v-model="task.email_data.body"
        label="Body"
        type="textarea"
        :rows="12"
        class="custom-body"
      />
    </div>

    <div class="row justify-end q-gutter-sm">
      <f-btn
        appearance="primary"
        label="FORWARD"
        class="q-px-md text-uppercase"
      />
      <f-btn
        appearance="primary"
        label="REPLY"
        class="q-px-md text-uppercase"
      />
    </div>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import {
  useTaskStore,
  useDropdownStore,
  useGroupDropdownStore,
  useUserStore,
} from 'src/store/main';
import { isUndefinedOrNull } from 'src/utils/general';
import type { dynamicObj } from 'src/pages/assets';
import { priority_list, status_list } from 'src/constants/enum';
import { taskApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import { date } from 'quasar';
import { isAdmin, getUserDetailFromkey } from 'src/utils/UserDetails';
export default defineComponent({
  props: {},
    emits: ['btnClicked'],
  components: {},
  data() {
    return {
      taskTypeOptions: [
        { label: this.$t('task'), value: false },
        { label: this.$t('notification'), value: true },
      ],
    };
  },

  watch: {
    groups_loading: function (val: boolean) {
      if (val) {
        this.loadGroupsList();
      }
    },
    user_list_loading: function (val: boolean) {
      if (val) {
        this.loadUserList();
      }
    },
    data_fetched: function (val: boolean) {
      if (val) {
        this.isButtonVisible();
        this.convertDeadline();
      }
    },
  },
  mounted: function () {
    this.initView();
  },
  methods: {
    initView() {
      try {
        this.priorityOptions = priority_list.map((item: any) => {
          return {
            label: this.$t(item),
            value: item,
          };
        });

        this.statusOptions = status_list.map((item: any) => {
          return {
            label: this.$t(item),
            value: item,
          };
        });

        this.makeTimeOptions();
        this.convertDeadline();
        this.loadUserList();
        this.loadGroupsList();
        this.isButtonVisible();
      } catch (error) {
        logError(error);
      }
    },
    isButtonVisible() {
      this.assign_to_me = false;

      if (!this.data_fetched || !this.task.assigned_to_group_id) {
        return;
      }

      if (
        !this.task.hasOwnProperty('group_users') ||
        this.task.group_users.length === 0
      ) {
        return;
      }

      const current_user_id = this.getUserDetailByKey('id');
      for (const [index, id] of Object.entries(this.task.group_users)) {
        if (id === current_user_id) {
          this.assign_to_me = true;
        }
      }
    },

    convertDeadline() {
      try {
        if (!this.data_fetched || isUndefinedOrNull(this.task.deadline)) {
          return;
        }

        const { formated_date, formatted_time, formatted_deadline } =
          this.getDisplayDeadline(this.task.deadline);
        this.task.date = formated_date;
        this.task.time = formatted_time;
        this.task.deadline = formatted_deadline;
      } catch (error) {
        logError(error);
      }
    },

    OnTimeChange(time: any) {
      const deadline = this.makeDeadline(time, this.task.date);
      this.task.deadline = deadline;
    },

    OnDateChange(date: any) {
      const deadline = this.makeDeadline(this.task.time, date);
      this.task.deadline = deadline;
    },

    resetAssigned() {
      this.errors['assigned_to_group_id'] = '';
      this.errors['assigned_to_user_id'] = '';
      this.task.assigned_to_group_id = null;
      this.task.assigned_to_user_id = null;
    },

    loadUserList() {
      this.filteredUserList = this.usersList;
    },

    loadGroupsList() {
      this.filteredGroupList = this.group_list;
    },

    filterGroupsEvent(val: string, update: any, abort: any) {
      if (val.length < 1) {
        abort();
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filteredGroupList = this.group_list.filter(
          (v: any) => v.label.toLowerCase().startsWith(needle) as string,
        );
      });
    },

    filterUsersEvent(val: string, update: any, abort: any) {
      if (val.length < 1) {
        abort();
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filteredUserList = this.usersList.filter(
          (v: any) => v.label.toLowerCase().startsWith(needle) as string,
        );
      });
    },
    async finish_task() {
      this.task.status = 'done';
      await this.done();
    },
    async done() {
      await this.save();
      this.$router.push('/tasks');
      //this.$router.go(-1);
    },
    // save
    async save() {
      try {
        if (!this.validateForm()) {
          return;
        }
        this.processing = true;
        const data = Object.assign({} as dynamicObj, this.task);
        data.deadline = this.getIsoFormatDate(data.deadline);

        if (isUndefinedOrNull(data.assigned_to_group_id)) {
          data.assigned_to_group_id = '';
          data.assigned_to_group = '';
        }
        const response = await taskApiService.editTask(this.task.id, data);
        if (response.success === false) {
          throw response;
        }

        notify.success(this.$t('MSG_SAVE'));
        if (response.data.hasOwnProperty('group_users')) {
          this.task.group_users = response.data.group_users;
        }
      } catch (error) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      } finally {
        this.processing = false;
      }
    },

    validateForm() {
      this.errors = {} as dynamicObj;
      let valid = true;

      if (!this.task.title) {
        this.errors['title'] = this.$t('field_required');
        valid = false;
      }

      if (this.task.assigned_to_group) {
        if (!this.task.assigned_to_group_id) {
          this.errors['assigned_to_group_id'] = this.$t('field_required');
          valid = false;
        }
      } else {
        if (!this.task.assigned_to_user_id) {
          this.errors['assigned_to_user_id'] = this.$t('field_required');
          valid = false;
        }
      }

      return valid;
    },

    AssignToMe() {
      this.task.assigned_to_user_id = this.getUserDetailByKey('id');
      this.task.assigned_to_group_id = null;
      this.task.assigned_to_group = false;
      this.save();
    },
  },

  setup() {
    const task_store = useTaskStore();
    const {
      task,
      processing,
      data_fetched,
      timeOptions,
      task_date_format,
      userGroupIds,
    } = storeToRefs(task_store);
    const {
      getTasks,
      makeTimeOptions,
      getDeadlineTime,
      getIsoFormatDate,
      makeDeadline,
      getDisplayDeadline,
      isHasAccess,
    } = task_store;

    const categoryOptions = [
      { label: 'General', value: 'general' },
      { label: 'Urgent', value: 'urgent' },
    ];

    const dropdown_store = useDropdownStore();
    const filteredUserList: any = ref(dropdown_store.usersList);
    const { user_list_loading, usersList } = storeToRefs(dropdown_store);

    const group_dropdown_store = useGroupDropdownStore();
    const filteredGroupList: any = ref(group_dropdown_store.group_list);
    const { group_list, groups_loading } = storeToRefs(group_dropdown_store);

    const user_store = useUserStore();
    const { getUserDetailByKey } = user_store;

    return {
      getDisplayDeadline,
      makeDeadline,
      getIsoFormatDate,
      task_date_format,
      getDeadlineTime,
      userGroupIds,
      btnStatus: ref(false),
      getUserDetailByKey,
      timeOptions,
      makeTimeOptions,
      data_fetched,
      group_list,
      groups_loading,
      filteredGroupList,
      user_list_loading,
      usersList,
      filteredUserList,
      task,
      processing,
      getTasks,
      priorityOptions: ref([] as dynamicObj[]),
      statusOptions: ref([] as dynamicObj[]),
      show_calender: ref(false),
      errors: ref({} as dynamicObj),
      assign_to_me: ref(false),
      isHasAccess,
      categoryOptions,
    };
  },
});
</script>

<style scoped>
.custom-input,
.custom-select {
  background-color: white;
}

.text-h6 {
  color: #2c3e50;
  font-size: 18px;
}
</style>
